"use client"

import React from "react"
import { FlowShell } from "../_shared/FlowShell"
import { useFlowState } from "../_shared/useFlowState"
import { TABBY_INITIAL, TABBY_STEPS, TABBY_GREEN, TabbyData, TabbyStepProps } from "./schema"
import { Splash } from "./steps/Splash"
import { Country } from "./steps/Country"
import { Marketing } from "./steps/Marketing"
import { Phone } from "./steps/Phone"
import { OTP } from "./steps/OTP"
import { PIN } from "./steps/PIN"
import { TrustDevice } from "./steps/TrustDevice"
import { Privacy } from "./steps/Privacy"
import { Success } from "./steps/Success"

export default function TabbyFlowPage() {
  const flow = useFlowState<TabbyData>({
    totalSteps: TABBY_STEPS.length,
    initialData: TABBY_INITIAL,
  })

  const stepProps: TabbyStepProps = {
    data: flow.data,
    patch: flow.patch,
    next: flow.next,
    back: flow.back,
    goTo: flow.goTo,
  }

  const stepKey = TABBY_STEPS[flow.step]

  // Step-specific phone-frame tinting
  const isSplash = stepKey === "splash"
  const phoneBackground = isSplash ? TABBY_GREEN : "var(--atlas-background)"
  const statusBarTint = "dark" as const

  return (
    <FlowShell
      title="Tabby — iOS onboarding"
      step={flow.step}
      totalSteps={TABBY_STEPS.length}
      onReset={flow.reset}
      phoneBackground={phoneBackground}
      statusBarTint={statusBarTint}
      homeIndicatorTint="dark"
    >
      {stepKey === "splash" && <Splash {...stepProps} />}
      {stepKey === "country" && <Country {...stepProps} />}
      {stepKey === "marketing" && <Marketing {...stepProps} />}
      {stepKey === "phone" && <Phone {...stepProps} />}
      {stepKey === "otp" && <OTP {...stepProps} />}
      {stepKey === "pin" && <PIN {...stepProps} />}
      {stepKey === "trust" && <TrustDevice {...stepProps} />}
      {stepKey === "privacy" && <Privacy {...stepProps} />}
      {stepKey === "success" && <Success {...stepProps} />}
    </FlowShell>
  )
}

"use client"

import React from "react"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Card, CardContent } from "@atlas/ui-web/compositions/Card/Card"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import { TabbyStepProps } from "../schema"

/**
 * Success — simplified "stores" home that lands after onboarding.
 * Mirrors the last screen of the source flow at a high level only.
 */
export function Success({ goTo }: TabbyStepProps) {
  return (
    <div style={{ flex: 1, display: "flex", flexDirection: "column", overflowY: "auto" }}>
      {/* Header search */}
      <div style={{ padding: "var(--atlas-spacing-4) var(--atlas-spacing-5)" }}>
        <Input
          placeholder="Stores or products"
          leadingIcon={<span aria-hidden style={{ fontSize: 14 }}>🔍</span>}
          size="md"
        />
      </div>

      {/* Quick links */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "1fr 1fr",
          gap: "var(--atlas-spacing-3)",
          padding: "0 var(--atlas-spacing-5)",
        }}
      >
        <QuickLink emoji="🛒" title="All stores" sub="Shop and split" />
        <QuickLink emoji="🏷️" title="Deals" sub="Discounts up to 30%" />
      </div>

      {/* Categories row */}
      <div
        style={{
          display: "flex",
          gap: "var(--atlas-spacing-3)",
          padding: "var(--atlas-spacing-5)",
          overflowX: "auto",
        }}
      >
        {[
          { emoji: "💸", label: "Customise your Tabby" },
          { emoji: "📱", label: "Mobile" },
          { emoji: "💍", label: "Jewelry" },
        ].map((c) => (
          <div key={c.label} style={{ minWidth: 110 }}>
            <Card variant="outlined" size="sm">
              <CardContent>
                <div style={{ fontSize: 24 }}>{c.emoji}</div>
                <div
                  style={{
                    marginBlockStart: 6,
                    fontSize: "var(--atlas-font-size-xs)",
                    fontWeight: 600,
                    lineHeight: 1.3,
                  }}
                >
                  {c.label}
                </div>
              </CardContent>
            </Card>
          </div>
        ))}
      </div>

      {/* Invite friends card */}
      <div style={{ padding: "0 var(--atlas-spacing-5)" }}>
        <Card variant="filled">
          <CardContent>
            <div style={{ display: "flex", gap: "var(--atlas-spacing-3)", alignItems: "center" }}>
              <span aria-hidden style={{ fontSize: 28 }}>🏠</span>
              <div style={{ flex: 1 }}>
                <div style={{ fontSize: "var(--atlas-font-size-sm)", fontWeight: 600 }}>
                  Earn up to ₪200 by inviting friends to Tabby
                </div>
                <a
                  href="#"
                  onClick={(e) => e.preventDefault()}
                  style={{ fontSize: "var(--atlas-font-size-xs)", color: "var(--atlas-primary)", fontWeight: 600 }}
                >
                  Learn more
                </a>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Stores for you */}
      <div
        style={{
          padding: "var(--atlas-spacing-5) var(--atlas-spacing-5) 0",
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
        }}
      >
        <strong style={{ fontSize: "var(--atlas-font-size-base)" }}>Stores For You</strong>
        <a
          href="#"
          onClick={(e) => e.preventDefault()}
          style={{ fontSize: "var(--atlas-font-size-sm)", color: "var(--atlas-primary)", fontWeight: 600 }}
        >
          View all
        </a>
      </div>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(4, 1fr)",
          gap: "var(--atlas-spacing-2)",
          padding: "var(--atlas-spacing-3) var(--atlas-spacing-5)",
        }}
      >
        {["Cole", "Glamzale", "Ecco", "Mumzw"].map((store) => (
          <div
            key={store}
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: 4,
            }}
          >
            <div
              style={{
                width: 56,
                height: 56,
                borderRadius: "var(--atlas-radius-full)",
                background: "var(--atlas-background-muted)",
              }}
            />
            <span style={{ fontSize: "var(--atlas-font-size-xs)", color: "var(--atlas-foreground-muted)" }}>{store}</span>
          </div>
        ))}
      </div>

      <div style={{ flex: 1 }} />

      {/* Reset CTA so user can run the flow again */}
      <div style={{ padding: "var(--atlas-spacing-3) var(--atlas-spacing-5)" }}>
        <Badge size="sm" variant="success" dot>
          You&apos;re all set
        </Badge>
        <div style={{ marginBlockStart: "var(--atlas-spacing-2)" }}>
          <Button variant="outline" size="sm" onClick={() => goTo(0)}>
            Run the flow again
          </Button>
        </div>
      </div>

      {/* Bottom tab bar */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(4, 1fr)",
          padding: "var(--atlas-spacing-3) var(--atlas-spacing-4) var(--atlas-spacing-6)",
          borderTop: "1px solid var(--atlas-border)",
          background: "var(--atlas-background)",
        }}
      >
        {[
          { icon: "🔍", label: "Discover", active: true },
          { icon: "🛍️", label: "Shop" },
          { icon: "💳", label: "Money" },
          { icon: "👤", label: "Profile" },
        ].map((t) => (
          <div
            key={t.label}
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: 2,
              color: t.active ? "var(--atlas-foreground)" : "var(--atlas-foreground-muted)",
            }}
          >
            <span aria-hidden style={{ fontSize: 18 }}>{t.icon}</span>
            <span style={{ fontSize: 10, fontWeight: 600 }}>{t.label}</span>
          </div>
        ))}
      </div>
    </div>
  )
}

function QuickLink({ emoji, title, sub }: { emoji: string; title: string; sub: string }) {
  return (
    <Card variant="outlined" size="sm" interactive>
      <CardContent>
        <div style={{ display: "flex", alignItems: "center", gap: "var(--atlas-spacing-2)" }}>
          <span aria-hidden style={{ fontSize: 18 }}>{emoji}</span>
          <div style={{ fontSize: "var(--atlas-font-size-sm)", fontWeight: 600 }}>{title}</div>
        </div>
        <div style={{ fontSize: "var(--atlas-font-size-xs)", color: "var(--atlas-foreground-muted)", marginBlockStart: 2 }}>
          {sub}
        </div>
      </CardContent>
    </Card>
  )
}

"use client"

import React from "react"

/**
 * Shared screen chrome for Tabby step screens — a thin header row
 * with optional back and close affordances.
 */
export function ScreenHeader({
  onBack,
  onClose,
  closeLabel = "Close",
  rightSlot,
}: {
  onBack?: () => void
  onClose?: () => void
  closeLabel?: string
  rightSlot?: React.ReactNode
}) {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        height: 44,
      }}
    >
      <div>
        {onBack && (
          <button
            type="button"
            aria-label="Back"
            onClick={onBack}
            style={iconBtnStyle}
          >
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden>
              <path
                d="M15 18l-6-6 6-6"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </button>
        )}
      </div>
      <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
        {rightSlot}
        {onClose && (
          <button
            type="button"
            aria-label={closeLabel}
            onClick={onClose}
            style={iconBtnStyle}
          >
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden>
              <path
                d="M6 6l12 12M6 18L18 6"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
              />
            </svg>
          </button>
        )}
      </div>
    </div>
  )
}

const iconBtnStyle: React.CSSProperties = {
  width: 36,
  height: 36,
  display: "inline-flex",
  alignItems: "center",
  justifyContent: "center",
  background: "transparent",
  border: 0,
  cursor: "pointer",
  color: "var(--atlas-foreground)",
  borderRadius: "var(--atlas-radius-full)",
}

/**
 * Big circular illustration disc — used by trust/privacy/PIN intro screens.
 */
export function IllustrationDisc({
  emoji,
  tint = "var(--atlas-primary-subtle)",
  fg = "var(--atlas-primary)",
}: {
  emoji: string
  tint?: string
  fg?: string
}) {
  return (
    <div
      aria-hidden
      style={{
        width: 56,
        height: 56,
        borderRadius: "var(--atlas-radius-full)",
        background: tint,
        color: fg,
        display: "inline-flex",
        alignItems: "center",
        justifyContent: "center",
        fontSize: 28,
      }}
    >
      {emoji}
    </div>
  )
}

"use client"

/**
 * Atlas Dialog — modal / sheet / drawer surface
 *
 * Powered by @radix-ui/react-dialog for:
 *   - focus trap (Tab / Shift+Tab cycles inside content)
 *   - scroll lock (body scroll disabled while open)
 *   - keyboard dismiss (Escape key)
 *   - aria-modal, aria-labelledby, aria-describedby wiring
 *   - click-outside dismiss via onInteractOutside
 *
 * Variants:  modal (default) | sheet | drawer
 * Sizes:     sm | md | lg | xl | full
 *
 * Compound API:
 *   <Dialog open onOpenChange={...}>
 *     <DialogTrigger asChild><Button>Open</Button></DialogTrigger>
 *     <DialogContent variant="modal" size="md">
 *       <DialogHeader>
 *         <DialogTitle>…</DialogTitle>
 *         <DialogDescription>…</DialogDescription>
 *       </DialogHeader>
 *       <DialogBody>…</DialogBody>
 *       <DialogFooter>
 *         <DialogClose asChild><Button variant="outline">Cancel</Button></DialogClose>
 *         <Button>Confirm</Button>
 *       </DialogFooter>
 *     </DialogContent>
 *   </Dialog>
 *
 * Accessibility:
 *   - role="dialog" + aria-modal="true" via Radix
 *   - aria-labelledby → DialogTitle id (Radix auto-wires)
 *   - aria-describedby → DialogDescription id (Radix auto-wires)
 *   - Initial focus → first focusable element inside DialogContent
 *   - Escape → closes (unless closeOnEscape=false)
 *   - Focus returns to trigger on close
 *
 * Token compliance: all values via semantic tokens in Dialog.module.css.
 */

import React, { useId } from "react"
import * as RadixDialog from "@radix-ui/react-dialog"
import styles from "./Dialog.module.css"

/* ── Helpers ────────────────────────────────────────────────────── */

function cx(...classes: (string | false | null | undefined)[]): string {
  return classes.filter(Boolean).join(" ")
}

/* ── Types ──────────────────────────────────────────────────────── */

export type DialogVariant = "modal" | "sheet" | "drawer"
export type DialogSize    = "sm" | "md" | "lg" | "xl" | "full"
export type DialogSide    = "start" | "end"

/* ── Dialog root ────────────────────────────────────────────────── */
/*
 * Thin wrapper around Radix Root.
 * Supports both controlled (open + onOpenChange) and uncontrolled (defaultOpen).
 */

export interface DialogProps {
  open?:          boolean
  defaultOpen?:   boolean
  /** Called with next open state; use setOpen directly (receives boolean) */
  onOpenChange?:  (open: boolean) => void
  /** @deprecated — use onOpenChange instead */
  onClose?:       () => void
  children?:      React.ReactNode
}

export function Dialog({ open, defaultOpen, onOpenChange, onClose, children }: DialogProps) {
  const handleChange = (next: boolean) => {
    onOpenChange?.(next)
    if (!next) onClose?.()
  }

  return (
    <RadixDialog.Root
      open={open}
      defaultOpen={defaultOpen}
      onOpenChange={handleChange}
    >
      {children}
    </RadixDialog.Root>
  )
}

/* ── DialogTrigger ──────────────────────────────────────────────── */

export interface DialogTriggerProps {
  asChild?:  boolean
  children?: React.ReactNode
}

export function DialogTrigger({ asChild = true, children }: DialogTriggerProps) {
  return (
    <RadixDialog.Trigger asChild={asChild}>
      {children}
    </RadixDialog.Trigger>
  )
}

/* ── DialogContent ──────────────────────────────────────────────── */
/*
 * Renders: Portal → Overlay → Content surface.
 * Variant / size classes applied here.
 * Sheet gets the drag handle at the top.
 */

export interface DialogContentProps {
  variant?:             DialogVariant
  size?:                DialogSize
  /** Drawer only: which edge to slide from */
  side?:                DialogSide
  id?:                  string
  closeOnEscape?:       boolean
  closeOnOverlayClick?: boolean
  className?:           string
  children?:            React.ReactNode
}

export function DialogContent({
  variant             = "modal",
  size                = "md",
  side                = "end",
  id,
  closeOnEscape       = true,
  closeOnOverlayClick = true,
  className,
  children,
}: DialogContentProps) {
  const contentClasses = cx(
    styles.content,
    styles[variant],
    size !== "md" && styles[size],
    className,
  )

  return (
    <RadixDialog.Portal>
      {/* Overlay */}
      <RadixDialog.Overlay className={styles.overlay} />

      {/* Content surface */}
      <RadixDialog.Content
        id={id}
        className={contentClasses}
        data-side={variant === "drawer" ? side : undefined}
        onEscapeKeyDown={(e) => { if (!closeOnEscape) e.preventDefault() }}
        onInteractOutside={(e) => { if (!closeOnOverlayClick) e.preventDefault() }}
      >
        {/* Drag handle — sheet only; visual affordance only (FIX BUG-037 + BUG-066)
             Not interactive: close is via header × button or swipe gesture.
             aria-hidden prevents screen readers from announcing the decoration. */}
        {variant === "sheet" && (
          <div className={styles.dragHandle} aria-hidden="true" />
        )}

        {children}
      </RadixDialog.Content>
    </RadixDialog.Portal>
  )
}

/* ── DialogHeader ───────────────────────────────────────────────── */
/*
 * Horizontal row: [main slot] [close button].
 * showClose=true by default — renders a RadixDialog.Close button.
 * Pass showClose=false if you want no built-in × (or use DialogClose yourself).
 */

export interface DialogHeaderProps {
  showClose?: boolean
  /** @deprecated — close is now handled by Radix; prop accepted but ignored */
  onClose?:   () => void
  className?: string
  children?:  React.ReactNode
}

export function DialogHeader({ showClose = true, className, children }: DialogHeaderProps) {
  return (
    <div className={cx(styles.header, className)}>
      <div className={styles.headerMain}>
        {children}
      </div>

      {showClose && (
        <RadixDialog.Close
          className={styles.closeBtn}
          aria-label="Close dialog"
        >
          ✕
        </RadixDialog.Close>
      )}
    </div>
  )
}

/* ── DialogTitle ────────────────────────────────────────────────── */
/*
 * Wrapped in RadixDialog.Title for aria-labelledby wiring.
 * Required for accessibility — every dialog must have a title.
 */

export interface DialogTitleProps {
  className?: string
  children?:  React.ReactNode
}

export function DialogTitle({ className, children }: DialogTitleProps) {
  return (
    <RadixDialog.Title className={cx(styles.title, className)}>
      {children}
    </RadixDialog.Title>
  )
}

/* ── DialogDescription ──────────────────────────────────────────── */
/*
 * Wrapped in RadixDialog.Description for aria-describedby wiring.
 */

export interface DialogDescriptionProps {
  className?: string
  children?:  React.ReactNode
}

export function DialogDescription({ className, children }: DialogDescriptionProps) {
  return (
    <RadixDialog.Description className={cx(styles.description, className)}>
      {children}
    </RadixDialog.Description>
  )
}

/* ── DialogBody ─────────────────────────────────────────────────── */

export interface DialogBodyProps {
  className?: string
  children?:  React.ReactNode
}

export function DialogBody({ className, children }: DialogBodyProps) {
  return (
    <div className={cx(styles.body, className)}>
      {children}
    </div>
  )
}

/* ── DialogFooter ───────────────────────────────────────────────── */

export interface DialogFooterProps {
  justify?:   "start" | "between" | "end"
  className?: string
  children?:  React.ReactNode
}

export function DialogFooter({ justify = "end", className, children }: DialogFooterProps) {
  const justifyClass =
    justify === "between" ? styles.footerBetween :
    justify === "start"   ? styles.footerStart   :
    styles.footerEnd

  return (
    <div className={cx(styles.footer, justifyClass, className)}>
      {children}
    </div>
  )
}

/* ── DialogClose ────────────────────────────────────────────────── */
/*
 * Wraps any element to close the dialog on click.
 * Use asChild=true (default) to render the child element as the trigger.
 */

export interface DialogCloseProps {
  asChild?:  boolean
  children?: React.ReactNode
}

export function DialogClose({ asChild = true, children }: DialogCloseProps) {
  return (
    <RadixDialog.Close asChild={asChild}>
      {children}
    </RadixDialog.Close>
  )
}

