/**
 * Send Money flow — shared types, constants, and step list.
 */

export type Recipient = {
  id: string
  name: string
  /** Masked account/IBAN, e.g. "•••• 4471" */
  account: string
  currency: string
  /** Emoji avatar stand-in */
  avatar: string
}

export const RECENT_RECIPIENTS: Recipient[] = [
  { id: "r1", name: "Amara Okafor", account: "•••• 4471", currency: "EUR", avatar: "👩🏾" },
  { id: "r2", name: "Diego Fernandez", account: "•••• 9902", currency: "USD", avatar: "🧑🏽" },
  { id: "r3", name: "Priya Nair", account: "•••• 2210", currency: "INR", avatar: "👩🏽" },
  { id: "r4", name: "Tom Whitfield", account: "•••• 7734", currency: "GBP", avatar: "🧑🏻" },
]

export type SendMoneyData = {
  recipient: Recipient | null
  search: string
  sendAmount: string
  sendCurrency: string
  receiveCurrency: string
  submitting: boolean
  confirmOpen: boolean
  sent: boolean
}

export const SEND_MONEY_INITIAL: SendMoneyData = {
  recipient: null,
  search: "",
  sendAmount: "",
  sendCurrency: "GBP",
  receiveCurrency: "EUR",
  submitting: false,
  confirmOpen: false,
  sent: false,
}

/** Fixed demo FX rate: 1 GBP -> 1.17 EUR */
export const FX_RATE = 1.17
/** Flat demo fee in send-currency units */
export const FEE = 2.49

export function parseAmount(raw: string): number {
  const n = Number(raw.replace(/,/g, ""))
  return Number.isFinite(n) ? n : 0
}

export function isAmountValid(raw: string): boolean {
  const n = parseAmount(raw)
  return n > 0 && n <= 1_000_000
}

export function convert(sendAmount: number): number {
  return Math.max(0, (sendAmount - FEE) * FX_RATE)
}

/** Step order — order of indices the user moves through */
export const SEND_MONEY_STEPS = ["recipient", "amount", "review"] as const

export type SendMoneyStepKey = (typeof SEND_MONEY_STEPS)[number]

/** Props every Send Money step receives */
export type SendMoneyStepProps = {
  data: SendMoneyData
  patch: (partial: Partial<SendMoneyData>) => void
  next: () => void
  back: () => void
  goTo: (index: number) => void
  reset: () => void
}

