"use client"

import React from "react"

/**
 * Shared screen chrome for Send Money step screens — a thin header row
 * with a title and optional back affordance.
 */
export function ScreenHeader({
  title,
  onBack,
}: {
  title: string
  onBack?: () => void
}) {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: "var(--atlas-spacing-2)",
        height: 44,
      }}
    >
      {onBack && (
        <button
          type="button"
          aria-label="Back"
          onClick={onBack}
          style={{
            width: 36,
            height: 36,
            display: "inline-flex",
            alignItems: "center",
            justifyContent: "center",
            background: "transparent",
            border: 0,
            cursor: "pointer",
            color: "var(--atlas-foreground)",
            borderRadius: "var(--atlas-radius-full)",
            marginInlineStart: -8,
          }}
        >
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden>
            <path
              d="M15 18l-6-6 6-6"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </button>
      )}
      <strong style={{ fontSize: "var(--atlas-font-size-lg)", fontWeight: 700 }}>{title}</strong>
    </div>
  )
}

