"use client"

import React from "react"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Card, CardContent } from "@atlas/ui-web/compositions/Card/Card"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import { RECENT_RECIPIENTS, Recipient, SendMoneyStepProps } from "../schema"
import { ScreenHeader } from "./_chrome"

export function RecipientStep({ data, patch, next }: SendMoneyStepProps) {
  const query = data.search.trim().toLowerCase()
  const filtered = RECENT_RECIPIENTS.filter((r) =>
    query.length === 0 ? true : r.name.toLowerCase().includes(query),
  )

  const handleSelect = (recipient: Recipient) => {
    patch({ recipient, sendCurrency: "GBP", receiveCurrency: recipient.currency })
    next()
  }

  return (
    <div
      style={{
        flex: 1,
        display: "flex",
        flexDirection: "column",
        padding: "var(--atlas-spacing-3) var(--atlas-spacing-5) var(--atlas-spacing-5)",
        overflowY: "auto",
      }}
    >
      <ScreenHeader title="Send money" />

      <div style={{ marginBlockStart: "var(--atlas-spacing-4)" }}>
        <Input
          aria-label="Search recipients"
          placeholder="Search name or add new"
          value={data.search}
          onChange={(e) => patch({ search: e.target.value })}
          leadingIcon={<span aria-hidden style={{ fontSize: 14 }}>🔍</span>}
          size="lg"
        />
      </div>

      <div
        style={{
          marginBlockStart: "var(--atlas-spacing-5)",
          fontSize: "var(--atlas-font-size-xs)",
          fontWeight: 600,
          color: "var(--atlas-foreground-muted)",
          textTransform: "uppercase",
          letterSpacing: "0.04em",
        }}
      >
        Recent recipients
      </div>

      <div
        style={{
          marginBlockStart: "var(--atlas-spacing-3)",
          display: "flex",
          flexDirection: "column",
          gap: "var(--atlas-spacing-2)",
        }}
      >
        {filtered.length === 0 && (
          <p style={{ color: "var(--atlas-foreground-muted)", fontSize: "var(--atlas-font-size-sm)" }}>
            No recipients match &ldquo;{data.search}&rdquo;.
          </p>
        )}

        {filtered.map((r) => (
          <Card
            key={r.id}
            variant="outlined"
            size="sm"
            interactive
            onClick={() => handleSelect(r)}
          >
            <CardContent>
              <div style={{ display: "flex", alignItems: "center", gap: "var(--atlas-spacing-3)" }}>
                <span
                  aria-hidden
                  style={{
                    width: 40,
                    height: 40,
                    borderRadius: "var(--atlas-radius-full)",
                    background: "var(--atlas-background-muted)",
                    display: "inline-flex",
                    alignItems: "center",
                    justifyContent: "center",
                    fontSize: 20,
                    flexShrink: 0,
                  }}
                >
                  {r.avatar}
                </span>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: "var(--atlas-font-size-sm)", fontWeight: 600 }}>{r.name}</div>
                  <div style={{ fontSize: "var(--atlas-font-size-xs)", color: "var(--atlas-foreground-muted)" }}>
                    {r.account}
                  </div>
                </div>
                <Badge size="sm" variant="secondary">
                  {r.currency}
                </Badge>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  )
}

