"use client"

import React from "react"
import { FlowShell } from "../_shared/FlowShell"
import { useFlowState } from "../_shared/useFlowState"
import { SEND_MONEY_INITIAL, SEND_MONEY_STEPS, SendMoneyData, SendMoneyStepProps } from "./schema"
import { RecipientStep } from "./steps/Recipient"
import { AmountStep } from "./steps/Amount"
import { ReviewStep } from "./steps/Review"

export default function SendMoneyFlowPage() {
  const flow = useFlowState<SendMoneyData>({
    totalSteps: SEND_MONEY_STEPS.length,
    initialData: SEND_MONEY_INITIAL,
  })

  const stepProps: SendMoneyStepProps = {
    data: flow.data,
    patch: flow.patch,
    next: flow.next,
    back: flow.back,
    goTo: flow.goTo,
    reset: flow.reset,
  }

  const stepKey = SEND_MONEY_STEPS[flow.step]

  return (
    <FlowShell
      title="Send Money"
      step={flow.step}
      totalSteps={SEND_MONEY_STEPS.length}
      onReset={flow.reset}
      statusBarTint="dark"
      homeIndicatorTint="dark"
    >
      {stepKey === "recipient" && <RecipientStep {...stepProps} />}
      {stepKey === "amount" && <AmountStep {...stepProps} />}
      {stepKey === "review" && <ReviewStep {...stepProps} />}
    </FlowShell>
  )
}

